-- Demo data: three small Colombian merchants. Prices are in Colombian pesos (COP).
-- Ids are generated by the database, so each product finds its store by slug.

INSERT INTO store (name, slug, description) VALUES
    ('Café La Palma', 'cafe-la-palma',
     'Café de origen cultivado por familias caficultoras del Quindío.'),
    ('Tejidos Doña Rosa', 'tejidos-dona-rosa',
     'Ruanas, mochilas y tejidos hechos a mano en Boyacá.'),
    ('Dulces del Valle', 'dulces-del-valle',
     'Dulces típicos y postres tradicionales del Valle del Cauca.');

INSERT INTO product (store_id, name, slug, description, price)
SELECT s.id, p.name, p.slug, p.description, p.price
FROM (VALUES
    ('cafe-la-palma', 'Café molido Quindío 500 g', 'cafe-molido-quindio-500g',
     'Café arábica de tueste medio, molido para greca o cafetera de filtro.', 32000.00),
    ('cafe-la-palma', 'Café en grano Supremo 1 kg', 'cafe-en-grano-supremo-1kg',
     'Grano entero tipo Supremo con notas de panela y cítricos.', 58000.00),
    ('cafe-la-palma', 'Panela orgánica en bloque 1 kg', 'panela-organica-bloque-1kg',
     'Panela de caña sin aditivos, ideal para aguapanela.', 9500.00),
    ('cafe-la-palma', 'Prensa francesa 600 ml', 'prensa-francesa-600ml',
     'Cafetera de émbolo en vidrio templado para tres tazas.', 74900.00),
    ('tejidos-dona-rosa', 'Ruana de lana virgen', 'ruana-de-lana-virgen',
     'Ruana tradicional boyacense tejida en telar con lana de oveja.', 185000.00),
    ('tejidos-dona-rosa', 'Mochila tejida a mano', 'mochila-tejida-a-mano',
     'Mochila de fique con diseños geométricos y gaza reforzada.', 120000.00),
    ('tejidos-dona-rosa', 'Gorro de lana para niño', 'gorro-de-lana-nino',
     'Gorro abrigado de lana suave, talla única infantil.', 28000.00),
    ('tejidos-dona-rosa', 'Bufanda de alpaca', 'bufanda-de-alpaca',
     'Bufanda liviana y cálida en tonos tierra.', 65000.00),
    ('dulces-del-valle', 'Arequipe artesanal 500 g', 'arequipe-artesanal-500g',
     'Dulce de leche cocido a fuego lento en paila de cobre.', 16500.00),
    ('dulces-del-valle', 'Bocadillo veleño x 12', 'bocadillo-veleno-x12',
     'Bocadillo de guayaba envuelto en hoja de bijao, caja de 12 unidades.', 14000.00),
    ('dulces-del-valle', 'Manjar blanco en totuma', 'manjar-blanco-en-totuma',
     'Manjar blanco vallecaucano servido en totuma tradicional.', 22000.00),
    ('dulces-del-valle', 'Cocadas surtidas x 6', 'cocadas-surtidas-x6',
     'Cocadas de coco rallado con panela, paquete de seis.', 12000.00)
) AS p (store_slug, name, slug, description, price)
JOIN store s ON s.slug = p.store_slug;
